import { useState, useEffect, useCallback, useRef } from 'react';
import { useTranslation } from 'react-i18next';
import { CheckCircle, XCircle, Loader2, Save, Layers, Map } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import clsx from 'clsx';
import Button from '../ui/Button';
import Text from '../ui/Text';
import { TextColors, TextVariants } from '../../types/typography';

interface FocusStackModalProps {
  error: string | null;
  finalImageBase64: string | null;
  depthMapBase64?: string | null;
  imageCount?: number;
  isOpen: boolean;
  isProcessing: boolean;
  loadingImageUrl?: string | null;
  onClose(): void;
  onOpenFile(path: string): void;
  onSave(): Promise<string>;
  onMerge(): void;
  progressMessage: string | null;
}

export default function FocusStackModal({
  error,
  finalImageBase64,
  depthMapBase64,
  imageCount,
  isOpen,
  isProcessing,
  loadingImageUrl,
  onClose,
  onOpenFile,
  onSave,
  onMerge,
  progressMessage,
}: FocusStackModalProps) {
  const { t } = useTranslation();
  const [isMounted, setIsMounted] = useState(false);
  const [show, setShow] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [savedPath, setSavedPath] = useState<string | null>(null);
  const [showDepthMap, setShowDepthMap] = useState(false);

  const mouseDownTarget = useRef<EventTarget | null>(null);

  useEffect(() => {
    if (isOpen) {
      setIsMounted(true);
      const timer = setTimeout(() => setShow(true), 10);
      return () => clearTimeout(timer);
    } else {
      setShow(false);
      const timer = setTimeout(() => {
        setIsMounted(false);
        setSavedPath(null);
        setIsSaving(false);
        setShowDepthMap(false);
      }, 300);
      return () => clearTimeout(timer);
    }
  }, [isOpen]);

  const handleClose = useCallback(() => {
    if (isSaving) return;
    onClose();
  }, [onClose, isSaving]);

  const handleBackdropMouseDown = (e: React.MouseEvent) => {
    mouseDownTarget.current = e.target;
  };

  const handleBackdropClick = (e: React.MouseEvent) => {
    if (e.target === e.currentTarget && mouseDownTarget.current === e.currentTarget) {
      handleClose();
    }
    mouseDownTarget.current = null;
  };

  const handleSave = async () => {
    setIsSaving(true);
    try {
      const path = await onSave();
      setSavedPath(path);
    } catch (e) {
      console.error(e);
    } finally {
      setIsSaving(false);
    }
  };

  const handleOpen = () => {
    if (savedPath) {
      onOpenFile(savedPath);
      handleClose();
    }
  };

  const renderContent = () => {
    if (error) {
      return (
        <div className="flex flex-col items-center justify-center py-10 h-[460px]">
          <div className="flex items-center justify-center mb-6">
            <XCircle className="w-12 h-12 text-red-500" />
          </div>
          <Text variant={TextVariants.title} className="mb-2 text-center">
            {t('modals.focusStack.failed')}
          </Text>
          <Text className="text-center p-4 rounded-lg bg-bg-primary max-w-md mt-2 leading-relaxed">
            {String(error)}
          </Text>
        </div>
      );
    }

    if (finalImageBase64 && !isProcessing) {
      const activeSrc = showDepthMap && depthMapBase64 ? depthMapBase64 : finalImageBase64;

      return (
        <div className="w-full flex flex-col items-center">
          <div className="group relative w-full max-h-[500px] bg-[#111] rounded-lg overflow-hidden border border-surface flex items-center justify-center select-none">
            <img
              src={activeSrc}
              alt={showDepthMap ? 'Depth Map' : 'Stacked Focus'}
              className="w-full h-full object-contain max-h-[500px] transition-all duration-200"
              draggable={false}
            />

            {depthMapBase64 && (
              <div
                className="absolute bottom-6 left-1/2 -translate-x-1/2 flex items-center gap-1 bg-black/70 backdrop-blur-md p-1.5 rounded-full border border-white/10 shadow-xl z-20 pointer-events-auto opacity-0 group-hover:opacity-100 transition-opacity duration-200"
                onMouseDown={(e) => e.stopPropagation()}
              >
                <button
                  type="button"
                  onClick={() => setShowDepthMap(false)}
                  className={clsx(
                    'flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-medium transition-colors select-none',
                    !showDepthMap ? 'bg-accent text-button-text' : 'text-white/60 hover:bg-white/10 hover:text-white',
                  )}
                >
                  <Layers size={14} />
                  <span>{t('modals.focusStack.result')}</span>
                </button>

                <button
                  type="button"
                  onClick={() => setShowDepthMap(true)}
                  className={clsx(
                    'flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-medium transition-colors select-none',
                    showDepthMap ? 'bg-accent text-button-text' : 'text-white/60 hover:bg-white/10 hover:text-white',
                  )}
                >
                  <Map size={14} />
                  <span>{t('modals.focusStack.depthMap')}</span>
                </button>
              </div>
            )}
          </div>

          {savedPath && (
            <motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3 }}>
              <Text
                as="div"
                variant={TextVariants.heading}
                color={TextColors.success}
                className="flex items-center justify-center gap-2 mt-4"
              >
                <CheckCircle className="w-5 h-5" />
                <span>{t('modals.focusStack.savedSuccess')}</span>
              </Text>
            </motion.div>
          )}
        </div>
      );
    }

    if (isProcessing) {
      return (
        <div className="flex h-[460px] overflow-hidden rounded-lg border border-surface">
          <div className="w-2/5 relative overflow-hidden shrink-0 bg-[#0a0a0a] flex items-center justify-center">
            {loadingImageUrl ? (
              <img src={loadingImageUrl} alt="Source preview" className="w-full h-full object-cover" />
            ) : (
              <div className="w-full h-full bg-surface/50" />
            )}
          </div>
          <div className="flex-1 flex flex-col items-center justify-center px-12 bg-bg-primary">
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.1, duration: 0.4 }}
              className="flex flex-col items-center w-full"
            >
              <Text variant={TextVariants.title} className="mb-2 text-center">
                {t('modals.focusStack.stacking')}
              </Text>
              <Text className="text-center font-mono h-6 flex justify-center items-center">
                {progressMessage || t('modals.focusStack.initializing')}
              </Text>
              <div className="mt-8 w-64 relative">
                <div className="h-1 bg-surface rounded-full overflow-hidden relative w-full shadow-xs">
                  <motion.div
                    className="absolute inset-y-0 w-[80%] bg-linear-to-r from-transparent via-accent to-transparent mix-blend-screen"
                    style={{ filter: 'blur(3px)' }}
                    animate={{ x: ['-150%', '150%'] }}
                    transition={{ repeat: Infinity, duration: 1.5, ease: [0.4, 0, 0.2, 1] }}
                  />
                </div>
              </div>
            </motion.div>
          </div>
        </div>
      );
    }

    return (
      <div className="flex flex-col items-center justify-center h-[460px]">
        <div className="flex items-center justify-center mb-6">
          <Layers className="w-12 h-12 text-accent" />
        </div>
        <Text variant={TextVariants.title} className="mb-3 text-center">
          {t('modals.focusStack.title')}
        </Text>
        <Text className="text-center max-w-md leading-relaxed text-text-secondary">
          {imageCount
            ? t('modals.focusStack.descriptionWithCount', { count: imageCount })
            : t('modals.focusStack.description')}
        </Text>
      </div>
    );
  };

  const renderButtons = () => {
    if (error) {
      return (
        <Button onClick={handleClose} className="w-full">
          {t('modals.focusStack.close')}
        </Button>
      );
    }

    if (savedPath) {
      return (
        <>
          <button
            onClick={handleClose}
            className="px-4 py-2 rounded-md text-text-secondary hover:bg-card-active transition-colors"
          >
            {t('modals.focusStack.close')}
          </button>
          <Button onClick={handleOpen}>{t('modals.focusStack.openInEditor')}</Button>
        </>
      );
    }

    const disabled = isProcessing || isSaving;

    return (
      <div className={`w-full flex items-center justify-end gap-2 ${disabled ? 'opacity-50 pointer-events-none' : ''}`}>
        <button
          onClick={handleClose}
          className="px-4 py-2 rounded-md text-text-secondary hover:bg-card-active transition-colors text-sm"
        >
          {finalImageBase64 ? t('modals.focusStack.close') : t('modals.focusStack.cancel')}
        </button>

        {!finalImageBase64 && (
          <Button onClick={onMerge} disabled={isProcessing} variant="primary">
            {isProcessing ? <Loader2 className="animate-spin mr-2" size={16} /> : <Layers className="mr-2" size={16} />}
            {t('modals.focusStack.start')}
          </Button>
        )}

        {finalImageBase64 && (
          <Button onClick={handleSave} disabled={isSaving || isProcessing}>
            {isSaving ? <Loader2 className="animate-spin mr-2" size={16} /> : <Save className="mr-2" size={16} />}
            {t('modals.focusStack.save')}
          </Button>
        )}
      </div>
    );
  };

  if (!isMounted) return null;

  return (
    <div
      className={`fixed inset-0 flex items-center justify-center z-50 bg-black/40 backdrop-blur-xs transition-opacity duration-300 ease-in-out ${
        show ? 'opacity-100' : 'opacity-0'
      }`}
      onMouseDown={handleBackdropMouseDown}
      onClick={handleBackdropClick}
    >
      <AnimatePresence>
        {show && (
          <motion.div
            initial={{ scale: 0.95, opacity: 0, y: -16 }}
            animate={{ scale: 1, opacity: 1, y: 0 }}
            exit={{ scale: 0.95, opacity: 0, y: -16 }}
            transition={{ duration: 0.2, ease: 'easeOut' }}
            className="bg-surface rounded-xl shadow-2xl p-6 w-full max-w-4xl"
            onClick={(e) => e.stopPropagation()}
            onMouseDown={(e) => e.stopPropagation()}
          >
            <div className="flex flex-col">
              {renderContent()}
              <div className={`mt-4 flex justify-end gap-3 ${savedPath ? '' : 'pt-4 border-t border-surface/50'}`}>
                {renderButtons()}
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

import { useState } from 'react';
import {
  History,
  Undo2,
  Redo2,
  Trash2,
  Clock,
  Camera,
  Bookmark,
  ChevronDown,
  ChevronRight,
  Edit2,
  Check,
  X,
} from 'lucide-react';
import { useHistoryStore } from '../../../stores/history-store';
import { useProjectStore } from '../../../stores/project-store';
import { formatDistanceToNow } from '../../../utils/time';

export function HistoryPanel() {
  const entries = useHistoryStore((s) => s.getEntries());
  const currentIndex = useHistoryStore((s) => s.getCurrentIndex());
  const snapshots = useHistoryStore((s) => s.getSnapshots());
  const clear = useHistoryStore((s) => s.clear);
  const canUndo = useHistoryStore((s) => s.canUndo);
  const canRedo = useHistoryStore((s) => s.canRedo);
  const createSnapshot = useHistoryStore((s) => s.createSnapshot);
  const restoreSnapshot = useHistoryStore((s) => s.restoreSnapshot);
  const deleteSnapshot = useHistoryStore((s) => s.deleteSnapshot);
  const renameSnapshot = useHistoryStore((s) => s.renameSnapshot);
  const goToEntry = useHistoryStore((s) => s.goToEntry);

  const { project, loadProject, undo, redo } = useProjectStore();

  const [showSnapshots, setShowSnapshots] = useState(true);
  const [editingSnapshotId, setEditingSnapshotId] = useState<string | null>(null);
  const [editingName, setEditingName] = useState('');

  const handleUndo = () => {
    undo();
  };

  const handleRedo = () => {
    redo();
  };

  const handleJumpToState = (index: number) => {
    if (index === currentIndex) return;
    const state = goToEntry(index);
    if (state) {
      loadProject(state);
    }
  };

  const handleCreateSnapshot = () => {
    if (!project) return;
    const name = `Snapshot ${snapshots.length + 1}`;
    createSnapshot(name, project);
  };

  const handleRestoreSnapshot = (id: string) => {
    const state = restoreSnapshot(id);
    if (state) {
      loadProject(state);
    }
  };

  const handleStartRename = (id: string, currentName: string) => {
    setEditingSnapshotId(id);
    setEditingName(currentName);
  };

  const handleSaveRename = () => {
    if (editingSnapshotId && editingName.trim()) {
      renameSnapshot(editingSnapshotId, editingName.trim());
    }
    setEditingSnapshotId(null);
    setEditingName('');
  };

  const handleCancelRename = () => {
    setEditingSnapshotId(null);
    setEditingName('');
  };

  return (
    <div className="h-full flex flex-col">
      <div className="flex items-center justify-between p-3 border-b border-border">
        <div className="flex items-center gap-2">
          <History size={16} className="text-muted-foreground" />
          <h3 className="text-sm font-medium text-foreground">History</h3>
          <span className="text-[10px] bg-muted px-1.5 py-0.5 rounded-full text-muted-foreground">
            {entries.length}
          </span>
        </div>

        <div className="flex items-center gap-1">
          <button
            onClick={handleUndo}
            disabled={!canUndo()}
            className="p-1.5 rounded-md text-muted-foreground hover:text-foreground hover:bg-accent disabled:opacity-40 disabled:hover:bg-transparent disabled:cursor-not-allowed transition-colors"
            title="Undo (Ctrl+Z)"
          >
            <Undo2 size={14} />
          </button>
          <button
            onClick={handleRedo}
            disabled={!canRedo()}
            className="p-1.5 rounded-md text-muted-foreground hover:text-foreground hover:bg-accent disabled:opacity-40 disabled:hover:bg-transparent disabled:cursor-not-allowed transition-colors"
            title="Redo (Ctrl+Shift+Z)"
          >
            <Redo2 size={14} />
          </button>
          <button
            onClick={() => clear(project ?? undefined)}
            disabled={entries.length === 0}
            className="p-1.5 rounded-md text-muted-foreground hover:text-destructive hover:bg-destructive/10 disabled:opacity-40 disabled:hover:bg-transparent disabled:cursor-not-allowed transition-colors"
            title="Clear history"
          >
            <Trash2 size={14} />
          </button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto">
        <div className="border-b border-border">
          <button
            onClick={() => setShowSnapshots(!showSnapshots)}
            className="w-full flex items-center gap-2 px-3 py-2 hover:bg-accent/50 transition-colors"
          >
            {showSnapshots ? <ChevronDown size={12} /> : <ChevronRight size={12} />}
            <Bookmark size={12} className="text-muted-foreground" />
            <span className="text-[11px] font-medium">Snapshots</span>
            <span className="text-[10px] text-muted-foreground ml-auto">{snapshots.length}</span>
          </button>

          {showSnapshots && (
            <div className="px-2 pb-2">
              <button
                onClick={handleCreateSnapshot}
                className="w-full flex items-center justify-center gap-1.5 px-2 py-1.5 mb-2 text-[10px] rounded bg-secondary hover:bg-secondary/80 transition-colors"
              >
                <Camera size={10} />
                New Snapshot
              </button>

              {snapshots.length === 0 ? (
                <p className="text-[10px] text-muted-foreground text-center py-2">
                  No snapshots yet
                </p>
              ) : (
                <div className="space-y-1">
                  {snapshots.map((snapshot) => (
                    <div
                      key={snapshot.id}
                      className="group flex items-center gap-2 px-2 py-1.5 rounded hover:bg-accent/50 transition-colors"
                    >
                      {editingSnapshotId === snapshot.id ? (
                        <div className="flex-1 flex items-center gap-1">
                          <input
                            type="text"
                            value={editingName}
                            onChange={(e) => setEditingName(e.target.value)}
                            onKeyDown={(e) => {
                              if (e.key === 'Enter') handleSaveRename();
                              if (e.key === 'Escape') handleCancelRename();
                            }}
                            className="flex-1 px-1 py-0.5 text-[10px] bg-background border border-border rounded"
                            autoFocus
                          />
                          <button
                            onClick={handleSaveRename}
                            className="p-0.5 text-green-500 hover:text-green-400"
                          >
                            <Check size={10} />
                          </button>
                          <button
                            onClick={handleCancelRename}
                            className="p-0.5 text-muted-foreground hover:text-foreground"
                          >
                            <X size={10} />
                          </button>
                        </div>
                      ) : (
                        <>
                          <button
                            onClick={() => handleRestoreSnapshot(snapshot.id)}
                            className="flex-1 text-left"
                          >
                            <p className="text-[10px] font-medium truncate">{snapshot.name}</p>
                            <p className="text-[9px] text-muted-foreground">
                              {formatDistanceToNow(snapshot.timestamp)}
                            </p>
                          </button>
                          <div className="hidden group-hover:flex items-center gap-0.5">
                            <button
                              onClick={() => handleStartRename(snapshot.id, snapshot.name)}
                              className="p-0.5 text-muted-foreground hover:text-foreground"
                            >
                              <Edit2 size={10} />
                            </button>
                            <button
                              onClick={() => deleteSnapshot(snapshot.id)}
                              className="p-0.5 text-muted-foreground hover:text-destructive"
                            >
                              <Trash2 size={10} />
                            </button>
                          </div>
                        </>
                      )}
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}
        </div>

        {entries.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-8 text-center">
            <Clock size={32} className="text-muted-foreground/50 mb-3" />
            <p className="text-xs text-muted-foreground">No history yet</p>
            <p className="text-[10px] text-muted-foreground/70 mt-1">
              Your actions will appear here
            </p>
          </div>
        ) : (
          <div className="py-1">
            {[...entries].reverse().map((entry, reverseIndex) => {
              const index = entries.length - 1 - reverseIndex;
              const isCurrent = index === currentIndex;
              const isFuture = index > currentIndex;

              return (
                <button
                  key={entry.id}
                  onClick={() => handleJumpToState(index)}
                  className={`w-full flex items-start gap-2 px-3 py-2 text-left transition-colors ${
                    isCurrent
                      ? 'bg-primary/10 border-l-2 border-primary'
                      : isFuture
                      ? 'opacity-50 hover:opacity-75 hover:bg-accent/50'
                      : 'hover:bg-accent'
                  }`}
                >
                  <div
                    className={`mt-0.5 w-2 h-2 rounded-full flex-shrink-0 ${
                      isCurrent
                        ? 'bg-primary'
                        : isFuture
                        ? 'bg-muted-foreground/30'
                        : 'bg-muted-foreground/50'
                    }`}
                  />
                  <div className="min-w-0 flex-1">
                    <p
                      className={`text-xs truncate ${
                        isCurrent ? 'font-medium text-foreground' : 'text-muted-foreground'
                      }`}
                    >
                      {entry.description}
                    </p>
                    <p className="text-[9px] text-muted-foreground/70">
                      {formatDistanceToNow(entry.timestamp)}
                    </p>
                  </div>
                </button>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}

import { create } from 'zustand';
import { subscribeWithSelector } from 'zustand/middleware';
import type { Command } from '@openreel/image-core/commands';
import type { Project } from '../types/project';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface HistoryEntry {
  id: string;
  timestamp: number;
  description: string;
}

interface CommandRecord {
  id: string;
  timestamp: number;
  command: Command;
}

interface Snapshot {
  id: string;
  name: string;
  timestamp: number;
  /** Serialised project state for this snapshot. */
  state: string;
  thumbnail?: string;
}

interface HistoryState {
  undoStack: CommandRecord[];
  redoStack: CommandRecord[];
  /** Serialised project state captured before the first command was recorded. */
  baseProject: string | null;
  maxSize: number;
  snapshots: Snapshot[];
}

interface HistoryActions {
  /**
   * Record and immediately apply `cmd` to `currentProject`.
   * Returns the updated project that callers must set into the project store.
   */
  execute: (cmd: Command, currentProject: Project) => Project;

  /**
   * Undo the most recent command.  Applies the inverse to `currentProject`
   * and returns the restored project, or `null` when nothing can be undone.
   */
  undo: (currentProject: Project) => Project | null;

  /**
   * Re-apply the most recently undone command to `currentProject`.
   * Returns the restored project or `null` when there is nothing to redo.
   */
  redo: (currentProject: Project) => Project | null;

  canUndo: () => boolean;
  canRedo: () => boolean;

  /**
   * Human-readable description of the command that would be undone next.
   */
  getUndoDescription: () => string | null;

  /**
   * Human-readable description of the command that would be redone next.
   */
  getRedoDescription: () => string | null;

  /**
   * Jump to an arbitrary position in the undo stack (0 = oldest, length-1 = newest).
   * Replays all commands from `baseProject` up to and including `index`.
   * Returns the project at that point or `null` on failure.
   */
  goToEntry: (index: number) => Project | null;

  /**
   * Derived list of entries for the HistoryPanel (newest first when reversed by consumer).
   */
  getEntries: () => HistoryEntry[];

  /** Current position: index of the entry that reflects the present project state. */
  getCurrentIndex: () => number;

  clear: (baseProject?: Project) => void;
  setMaxSize: (max: number) => void;

  // ── Named snapshots (checkpoint-style) ──────────────────────────────────

  createSnapshot: (name: string, project: Project, thumbnail?: string) => void;
  restoreSnapshot: (id: string) => Project | null;
  deleteSnapshot: (id: string) => void;
  renameSnapshot: (id: string, name: string) => void;
  getSnapshots: () => Snapshot[];
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

const generateId = () => `${Date.now()}-${Math.random().toString(36).slice(2, 11)}`;

// ---------------------------------------------------------------------------
// Store
// ---------------------------------------------------------------------------

export const useHistoryStore = create<HistoryState & HistoryActions>()(
  subscribeWithSelector((set, get) => ({
    undoStack: [],
    redoStack: [],
    baseProject: null,
    maxSize: 50,
    snapshots: [],

    execute: (cmd, currentProject) => {
      const { undoStack, maxSize, baseProject } = get();

      // Capture base project on first command ever.
      const base = baseProject ?? JSON.stringify(currentProject);

      // Attempt to coalesce with the most recent command via Command.merge.
      // Merge is called on the LAST (older) command with the NEW command as argument.
      if (undoStack.length > 0) {
        const last = undoStack[undoStack.length - 1];
        const merged = last.command.merge?.(cmd) ?? null;
        if (merged !== null) {
          const newProject = cmd.apply(currentProject);
          const updatedStack = [
            ...undoStack.slice(0, -1),
            { ...last, command: merged },
          ];
          set({
            undoStack: updatedStack,
            redoStack: [],
            baseProject: base,
          });
          return newProject;
        }
      }

      const newProject = cmd.apply(currentProject);

      const record: CommandRecord = {
        id: generateId(),
        timestamp: Date.now(),
        command: cmd,
      };

      let newStack = [...undoStack, record];
      if (newStack.length > maxSize) {
        // When we drop the oldest command we need to update baseProject to
        // the state *after* that command would have been applied so that
        // goToEntry remains correct.  We approximate by re-serialising the
        // project state that preceded the second-oldest command (i.e. we
        // compute the new base by applying the dropped command to the old
        // base and serialising that result).
        const dropped = newStack[0];
        let newBase: Project | null = null;
        try {
          const parsed = JSON.parse(base) as Project;
          newBase = dropped.command.apply(parsed);
        } catch {
          newBase = null;
        }
        newStack = newStack.slice(1);
        set({
          undoStack: newStack,
          redoStack: [],
          baseProject: newBase ? JSON.stringify(newBase) : base,
        });
      } else {
        set({ undoStack: newStack, redoStack: [], baseProject: base });
      }

      return newProject;
    },

    undo: (currentProject) => {
      const { undoStack, redoStack } = get();
      if (undoStack.length === 0) return null;

      const record = undoStack[undoStack.length - 1];
      const inverse = record.command.invert();
      const restoredProject = inverse.apply(currentProject);

      set({
        undoStack: undoStack.slice(0, -1),
        redoStack: [...redoStack, record],
      });

      return restoredProject;
    },

    redo: (currentProject) => {
      const { undoStack, redoStack } = get();
      if (redoStack.length === 0) return null;

      const record = redoStack[redoStack.length - 1];
      const newProject = record.command.apply(currentProject);

      set({
        undoStack: [...undoStack, record],
        redoStack: redoStack.slice(0, -1),
      });

      return newProject;
    },

    canUndo: () => get().undoStack.length > 0,
    canRedo: () => get().redoStack.length > 0,

    getUndoDescription: () => {
      const { undoStack } = get();
      return undoStack.length > 0 ? undoStack[undoStack.length - 1].command.description : null;
    },

    getRedoDescription: () => {
      const { redoStack } = get();
      return redoStack.length > 0 ? redoStack[redoStack.length - 1].command.description : null;
    },

    goToEntry: (index) => {
      const { undoStack, baseProject } = get();
      if (index < 0 || index >= undoStack.length) return null;
      if (!baseProject) return null;

      try {
        let project = JSON.parse(baseProject) as Project;
        for (let i = 0; i <= index; i++) {
          project = undoStack[i].command.apply(project);
        }
        // Commands past the target index become the redo stack, reversed so that
        // the next command to re-apply (index+1) is at the end (popped first on redo).
        const redoCommands = undoStack.slice(index + 1).reverse();
        set({ undoStack: undoStack.slice(0, index + 1), redoStack: redoCommands });
        return project;
      } catch {
        return null;
      }
    },

    getEntries: () =>
      get().undoStack.map((r) => ({
        id: r.id,
        timestamp: r.timestamp,
        description: r.command.description,
      })),

    getCurrentIndex: () => get().undoStack.length - 1,

    clear: (baseProject) => {
      set({
        undoStack: [],
        redoStack: [],
        baseProject: baseProject ? JSON.stringify(baseProject) : null,
      });
    },

    setMaxSize: (max) => set({ maxSize: max }),

    // ── Named snapshots ────────────────────────────────────────────────────

    createSnapshot: (name, project, thumbnail) => {
      const { snapshots } = get();
      const snapshot: Snapshot = {
        id: generateId(),
        name,
        timestamp: Date.now(),
        state: JSON.stringify(project),
        thumbnail,
      };
      set({ snapshots: [...snapshots, snapshot] });
    },

    restoreSnapshot: (id) => {
      const { snapshots } = get();
      const snapshot = snapshots.find((s) => s.id === id);
      if (!snapshot) return null;
      try {
        return JSON.parse(snapshot.state) as Project;
      } catch {
        return null;
      }
    },

    deleteSnapshot: (id) => {
      set({ snapshots: get().snapshots.filter((s) => s.id !== id) });
    },

    renameSnapshot: (id, name) => {
      set({
        snapshots: get().snapshots.map((s) => (s.id === id ? { ...s, name } : s)),
      });
    },

    getSnapshots: () => get().snapshots,
  }))
);

