use anyhow::{bail, Context, Result};
use konnect_sexp::{
    abandon_file_transaction, inspect_file_transactions, recover_file_transactions,
    TransactionTargetState,
};
use std::path::Path;

pub fn run(args: &[String]) -> Result<()> {
    match args.first().map(String::as_str) {
        Some("status") => status(exact_project_path(args, "status")?),
        Some("recover") => recover(exact_project_path(args, "recover")?),
        Some("abandon") => abandon(args),
        Some(command) => {
            bail!("unknown transaction command '{command}'; expected status, recover, or abandon")
        }
        None => bail!("transaction command required; expected status, recover, or abandon"),
    }
}

fn exact_project_path<'a>(args: &'a [String], command: &str) -> Result<&'a Path> {
    if args.len() != 2 {
        bail!("usage: konnect transaction {command} <project-dir>");
    }
    Ok(Path::new(&args[1]))
}

fn status(project: &Path) -> Result<()> {
    let statuses = inspect_file_transactions(project)
        .with_context(|| format!("failed to inspect transactions in {}", project.display()))?;
    if statuses.is_empty() {
        println!("No active transaction journals.");
        return Ok(());
    }

    for status in statuses {
        println!("Transaction {} ({})", status.id, status.journal.display());
        for target in status.targets {
            let state = match target.state {
                TransactionTargetState::Pending => "pending",
                TransactionTargetState::Applied => "applied",
                TransactionTargetState::Divergent => "divergent",
            };
            println!("  {state:9} {}", target.path.display());
        }
    }
    println!("Journal contents are redacted because they contain complete schematic images.");
    Ok(())
}

fn recover(project: &Path) -> Result<()> {
    let outcomes = recover_file_transactions(project)
        .with_context(|| format!("failed to recover transactions in {}", project.display()))?;
    if outcomes.is_empty() {
        println!("No active transaction journals.");
    } else {
        for outcome in outcomes {
            println!(
                "Recovered transaction {} (completed {} file(s)).",
                outcome.id, outcome.completed_files
            );
        }
    }
    Ok(())
}

fn abandon(args: &[String]) -> Result<()> {
    if args.len() != 4 || args[3] != "--force" {
        bail!("usage: konnect transaction abandon <project-dir> <transaction-id> --force");
    }
    let project = Path::new(&args[1]);
    let outcome = abandon_file_transaction(project, &args[2]).with_context(|| {
        format!(
            "failed to abandon transaction '{}' in {}",
            args[2],
            project.display()
        )
    })?;
    println!(
        "Abandoned transaction {} without modifying target files.",
        outcome.id
    );
    println!(
        "Evidence retained at {}.",
        outcome.abandoned_journal.display()
    );
    println!("Warning: the abandoned journal contains complete before/after schematic images.");
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn exact_project_path_rejects_extra_arguments() {
        let args = vec![
            "status".to_owned(),
            "project".to_owned(),
            "extra".to_owned(),
        ];
        assert!(exact_project_path(&args, "status").is_err());
    }

    #[test]
    fn abandon_requires_force() {
        let args = vec![
            "abandon".to_owned(),
            "project".to_owned(),
            "transaction".to_owned(),
        ];
        assert!(abandon(&args).is_err());
    }
}

import { describe, it, expect, afterEach } from "vitest";
import * as tui from "./tui.js";
import { createTempDir, createTempFile, cleanupDir, readFile } from "./helpers.js";

let dir;

afterEach(() => {
  tui.kill();
  if (dir) cleanupDir(dir);
});

describe("undo and redo", () => {
  it("should undo typed text", () => {
    dir = createTempDir();
    const file = createTempFile(dir, "undo.txt", "Base");

    tui.start(file);
    tui.waitFor("Base");

    tui.press("end");
    tui.type(" Added");
    tui.waitFor("Base Added");

    // " Added" is one group (space joins next word) → 1 undo
    tui.press("ctrl+z");

    const s0 = tui.snapshot();
    const { snapshots } = tui.run();
    expect(snapshots[s0]).not.toContain("Added");
    expect(snapshots[s0]).toContain("Base");
  });

  it("should redo after undo", () => {
    dir = createTempDir();
    const file = createTempFile(dir, "redo.txt", "Base");

    tui.start(file);
    tui.waitFor("Base");

    tui.press("end");
    tui.type(" Extra");
    tui.waitFor("Base Extra");

    // " Extra" is one group → 1 undo
    tui.press("ctrl+z");

    const s0 = tui.snapshot();

    tui.press("ctrl+y");

    const s1 = tui.snapshot();
    const { snapshots } = tui.run();
    expect(snapshots[s0]).not.toContain("Extra");
    expect(snapshots[s1]).toContain("Base Extra");
  });

  it("should persist undo state through save", () => {
    dir = createTempDir();
    const file = createTempFile(dir, "persist.txt", "First");

    tui.start(file);
    tui.waitFor("First");

    tui.press("end");
    tui.type(" Second");
    tui.waitFor("First Second");

    tui.press("ctrl+s");

    // Verify screen shows "First Second" after save
    const s0 = tui.snapshot();

    tui.type(" Third");
    tui.waitFor("First Second Third");

    // " Third" is one group → 1 undo
    tui.press("ctrl+z");

    tui.press("ctrl+s");

    const s1 = tui.snapshot();
    const { snapshots } = tui.run();

    expect(snapshots[s0]).toContain("First Second");
    expect(snapshots[s1]).not.toContain("Third");
    // After undo and save, file should contain "First Second" without "Third"
    const content = readFile(file);
    expect(content).toBe("First Second\n");
  });

  it("should undo word by word, not char by char", () => {
    dir = createTempDir();
    const file = createTempFile(dir, "group.txt", "");

    tui.start(file);

    tui.type("hello world");
    tui.waitFor("hello world");

    // One undo removes " world" (space belongs with next word)
    tui.press("ctrl+z");

    const s0 = tui.snapshot();

    // Next undo removes "hello"
    tui.press("ctrl+z");

    const s1 = tui.snapshot();
    const { snapshots } = tui.run();
    expect(snapshots[s0]).toContain("hello");
    expect(snapshots[s0]).not.toContain("hello world");
    expect(snapshots[s1]).not.toContain("hello");
  });

  it("should break undo group on cursor movement", () => {
    dir = createTempDir();
    const file = createTempFile(dir, "cursor.txt", "");

    tui.start(file);

    tui.type("ab");
    tui.press("arrow_left");
    tui.press("arrow_right");
    tui.type("cd");
    tui.waitFor("abcd");

    // First undo removes "cd" (typed after cursor movement)
    tui.press("ctrl+z");

    const s0 = tui.snapshot();
    const { snapshots } = tui.run();
    expect(snapshots[s0]).toContain("ab");
    expect(snapshots[s0]).not.toContain("abcd");
  });
});

package undo

import (
	"strings"
	"unicode"

	"github.com/eugenioenko/ttt/internal/core/buffer"
)

// EditCommand defines the interface for undoable buffer edits.
type EditCommand interface {
	Apply(b *buffer.Buffer)
	Undo(b *buffer.Buffer)
}

// UndoStack manages undo and redo stacks with automatic grouping of
// consecutive character inserts and deletes.
type UndoStack struct {
	undo           []EditCommand
	redo           []EditCommand
	grouping       bool
	savePoint      int
	inTransaction  bool
	transactionIdx int
	// DeleteCursorStart controls where the cursor lands after undoing a
	// DeleteSelectionCommand. When true, cursor goes to the start of the
	// restored text (Emacs convention); when false, to the end (default).
	DeleteCursorStart bool
}

func (s *UndoStack) BeginTransaction() {
	s.grouping = false
	s.inTransaction = true
	s.transactionIdx = len(s.undo)
}

func (s *UndoStack) EndTransaction() {
	if !s.inTransaction {
		return
	}
	idx := s.transactionIdx
	s.inTransaction = false
	s.grouping = false

	if idx >= len(s.undo) {
		return
	}

	cmds := make([]EditCommand, len(s.undo)-idx)
	copy(cmds, s.undo[idx:])
	s.undo = s.undo[:idx]
	s.undo = append(s.undo, &BatchCommand{Commands: cmds})
}

func (s *UndoStack) MarkSaved() {
	s.grouping = false
	s.savePoint = len(s.undo)
}

func (s *UndoStack) AtSavePoint() bool {
	return len(s.undo) == s.savePoint
}

// Push adds a command to the undo stack and clears the redo stack.
// Consecutive InsertRuneCommand or DeleteRuneCommand at adjacent positions
// are automatically grouped so a single undo reverses the whole sequence.
func (s *UndoStack) Push(cmd EditCommand) {
	s.redo = nil
	if s.grouping {
		if len(s.undo) > 0 {
			if grp, ok := s.undo[len(s.undo)-1].(*BatchCommand); ok {
				if canGroup(grp, cmd) {
					grp.Commands = append(grp.Commands, cmd)
					return
				}
			}
		}
		s.grouping = false
	}

	switch cmd.(type) {
	case *InsertRuneCommand, *DeleteRuneCommand:
		grp := &BatchCommand{Commands: []EditCommand{cmd}}
		s.undo = append(s.undo, grp)
		s.grouping = true
	default:
		s.undo = append(s.undo, cmd)
	}
}

// BreakGroup ends the current undo group so the next Push starts a new one.
func (s *UndoStack) BreakGroup() {
	s.grouping = false
}

// ContinueGroup allows subsequent rune inserts to be appended to the
// current top-of-stack entry. Used after replaceSelection so that typing
// over a selection groups the replacement with continued typing.
func (s *UndoStack) ContinueGroup() {
	s.grouping = true
}

func canGroup(grp *BatchCommand, cmd EditCommand) bool {
	if len(grp.Commands) == 0 {
		return false
	}
	last := grp.Commands[len(grp.Commands)-1]
	switch lc := last.(type) {
	case *InsertRuneCommand:
		if ic, ok := cmd.(*InsertRuneCommand); ok {
			if ic.Line != lc.Line || ic.Col != lc.Col+1 {
				return false
			}
			// Space/tab after non-space starts a new group (space belongs with the next word)
			if (ic.Rune == ' ' || ic.Rune == '\t') && lc.Rune != ' ' && lc.Rune != '\t' {
				return false
			}
			return true
		}
	case *DeleteRuneCommand:
		if dc, ok := cmd.(*DeleteRuneCommand); ok {
			return dc.Line == lc.Line && (dc.Col == lc.Col-1 || dc.Col == lc.Col)
		}
	}
	return false
}

// CursorPos represents a cursor position returned by Undo/Redo.
type CursorPos struct {
	Line, Col int
}

// Undo undoes the last command and returns where the cursor should be placed.
func (s *UndoStack) Undo(b *buffer.Buffer) *CursorPos {
	if len(s.undo) == 0 {
		return nil
	}
	s.grouping = false
	cmd := s.undo[len(s.undo)-1]
	s.undo = s.undo[:len(s.undo)-1]
	cmd.Undo(b)
	s.redo = append(s.redo, cmd)
	return s.cursorAfterUndo(cmd)
}

// Redo re-applies the last undone command and returns where the cursor should be placed.
func (s *UndoStack) Redo(b *buffer.Buffer) *CursorPos {
	if len(s.redo) == 0 {
		return nil
	}
	s.grouping = false
	cmd := s.redo[len(s.redo)-1]
	s.redo = s.redo[:len(s.redo)-1]
	cmd.Apply(b)
	s.undo = append(s.undo, cmd)
	return cursorAfterRedo(cmd)
}

func (s *UndoStack) cursorAfterUndo(cmd EditCommand) *CursorPos {
	switch c := cmd.(type) {
	case *InsertRuneCommand:
		return &CursorPos{c.Line, c.Col}
	case *DeleteRuneCommand:
		return &CursorPos{c.Line, c.Col + 1}
	case *InsertStringCommand:
		return &CursorPos{c.Line, c.Col}
	case *SplitLineCommand:
		return &CursorPos{c.Line, c.Col}
	case *JoinLineCommand:
		return &CursorPos{c.Line - 1, c.PrevLen}
	case *JoinNextLineCommand:
		return &CursorPos{c.Line, c.JoinCol}
	case *DeleteSelectionCommand:
		if s.DeleteCursorStart {
			return &CursorPos{c.StartLine, c.StartCol}
		}
		return &CursorPos{c.EndLine, c.EndCol}
	case *PasteCommand:
		return &CursorPos{c.Line, c.Col}
	case *BatchCommand:
		if len(c.Commands) > 0 {
			return s.cursorAfterUndo(c.Commands[0])
		}
	}
	return nil
}

func cursorAfterRedo(cmd EditCommand) *CursorPos {
	switch c := cmd.(type) {
	case *InsertRuneCommand:
		return &CursorPos{c.Line, c.Col + 1}
	case *DeleteRuneCommand:
		return &CursorPos{c.Line, c.Col}
	case *InsertStringCommand:
		return &CursorPos{c.Line, c.Col + len([]rune(c.Text))}
	case *SplitLineCommand:
		return &CursorPos{c.Line + 1, 0}
	case *JoinLineCommand:
		return &CursorPos{c.Line - 1, c.PrevLen}
	case *JoinNextLineCommand:
		return &CursorPos{c.Line, c.JoinCol}
	case *DeleteSelectionCommand:
		return &CursorPos{c.StartLine, c.StartCol}
	case *PasteCommand:
		lines := splitLines(c.Text)
		if len(lines) == 1 {
			return &CursorPos{c.Line, c.Col + len([]rune(lines[0]))}
		}
		return &CursorPos{c.Line + len(lines) - 1, len([]rune(lines[len(lines)-1]))}
	case *BatchCommand:
		if len(c.Commands) > 0 {
			return cursorAfterRedo(c.Commands[len(c.Commands)-1])
		}
	}
	return nil
}

// InsertRuneCommand implements EditCommand for inserting a rune.
type InsertRuneCommand struct {
	Line, Col int
	Rune      rune
}

func (c *InsertRuneCommand) Apply(b *buffer.Buffer) {
	b.InsertRune(c.Line, c.Col, c.Rune)
}

func (c *InsertRuneCommand) Undo(b *buffer.Buffer) {
	b.DeleteRune(c.Line, c.Col)
}

// DeleteRuneCommand implements EditCommand for deleting a rune.
type DeleteRuneCommand struct {
	Line, Col int
	Rune      rune
}

func (c *DeleteRuneCommand) Apply(b *buffer.Buffer) {
	if c.Line < 0 || c.Line >= len(b.Lines) {
		return
	}
	runes := []rune(b.Lines[c.Line])
	if c.Col < 0 || c.Col >= len(runes) {
		return
	}
	c.Rune = runes[c.Col]
	b.DeleteRune(c.Line, c.Col)
}

func (c *DeleteRuneCommand) Undo(b *buffer.Buffer) {
	b.InsertRune(c.Line, c.Col, c.Rune)
}

// SplitLineCommand implements EditCommand for splitting a line (Enter key).
type SplitLineCommand struct {
	Line, Col int
}

func (c *SplitLineCommand) Apply(b *buffer.Buffer) {
	if c.Line < 0 || c.Line >= len(b.Lines) {
		return
	}
	line := []rune(b.Lines[c.Line])
	col := c.Col
	if col < 0 {
		col = 0
	}
	if col > len(line) {
		col = len(line)
	}
	left := string(line[:col])
	right := string(line[col:])
	b.Lines[c.Line] = left
	b.InsertLine(c.Line+1, right)
}

func (c *SplitLineCommand) Undo(b *buffer.Buffer) {
	if c.Line+1 >= len(b.Lines) {
		return
	}
	b.Lines[c.Line] += b.Lines[c.Line+1]
	b.DeleteLine(c.Line + 1)
	b.Dirty = true
}

// JoinLineCommand implements EditCommand for joining a line with the previous one (Backspace at col 0).
type JoinLineCommand struct {
	Line    int
	PrevLen int
}

func (c *JoinLineCommand) Apply(b *buffer.Buffer) {
	if c.Line <= 0 || c.Line >= len(b.Lines) {
		return
	}
	c.PrevLen = len([]rune(b.Lines[c.Line-1]))
	b.Lines[c.Line-1] += b.Lines[c.Line]
	b.DeleteLine(c.Line)
	b.Dirty = true
}

func (c *JoinLineCommand) Undo(b *buffer.Buffer) {
	if c.Line-1 < 0 || c.Line-1 >= len(b.Lines) {
		return
	}
	combined := []rune(b.Lines[c.Line-1])
	left := string(combined[:c.PrevLen])
	right := string(combined[c.PrevLen:])
	b.Lines[c.Line-1] = left
	b.InsertLine(c.Line, right)
}

// JoinNextLineCommand implements EditCommand for joining the current line with the next one.
// It trims leading whitespace from the next line and joins with a single space
// (unless the current line ends with a space or the trimmed next line is empty).
type JoinNextLineCommand struct {
	Line     int    // the current line (joins with Line+1)
	JoinCol  int    // column where the join happened (set by Apply)
	NextText string // original text of the next line (for undo)
}

func (c *JoinNextLineCommand) Apply(b *buffer.Buffer) {
	if c.Line < 0 || c.Line >= len(b.Lines)-1 {
		return
	}
	currentLine := b.Lines[c.Line]
	nextLine := b.Lines[c.Line+1]
	c.NextText = nextLine

	trimmed := strings.TrimLeftFunc(nextLine, unicode.IsSpace)
	currentRunes := []rune(currentLine)
	c.JoinCol = len(currentRunes)

	separator := ""
	if len(currentRunes) > 0 && trimmed != "" && currentRunes[len(currentRunes)-1] != ' ' {
		separator = " "
	}

	b.Lines[c.Line] = currentLine + separator + trimmed
	b.DeleteLine(c.Line + 1)
	b.Dirty = true
}

func (c *JoinNextLineCommand) Undo(b *buffer.Buffer) {
	if c.Line < 0 || c.Line >= len(b.Lines) {
		return
	}
	// Restore the current line to its original length
	currentRunes := []rune(b.Lines[c.Line])
	b.Lines[c.Line] = string(currentRunes[:c.JoinCol])
	b.InsertLine(c.Line+1, c.NextText)
}

// InsertLineCommand implements EditCommand for inserting a line.
type InsertLineCommand struct {
	Idx  int
	Text string
}

func (c *InsertLineCommand) Apply(b *buffer.Buffer) {
	b.InsertLine(c.Idx, c.Text)
}

func (c *InsertLineCommand) Undo(b *buffer.Buffer) {
	b.DeleteLine(c.Idx)
}

type DeleteLineCommand struct {
	Idx  int
	Text string
}

func (c *DeleteLineCommand) Apply(b *buffer.Buffer) {
	if c.Idx < 0 || c.Idx >= len(b.Lines) {
		return
	}
	c.Text = b.Lines[c.Idx]
	b.DeleteLine(c.Idx)
	b.Dirty = true
}

func (c *DeleteLineCommand) Undo(b *buffer.Buffer) {
	b.InsertLine(c.Idx, c.Text)
}

type SwapLineCommand struct {
	Line1, Line2 int
}

func (c *SwapLineCommand) Apply(b *buffer.Buffer) {
	if c.Line1 < 0 || c.Line2 < 0 || c.Line1 >= len(b.Lines) || c.Line2 >= len(b.Lines) {
		return
	}
	b.Lines[c.Line1], b.Lines[c.Line2] = b.Lines[c.Line2], b.Lines[c.Line1]
	b.Dirty = true
}

func (c *SwapLineCommand) Undo(b *buffer.Buffer) {
	c.Apply(b)
}

// InsertStringCommand implements EditCommand for inserting multiple runes (e.g. tab spaces).
type InsertStringCommand struct {
	Line, Col int
	Text      string
}

func (c *InsertStringCommand) Apply(b *buffer.Buffer) {
	if c.Line < 0 || c.Line >= len(b.Lines) {
		return
	}
	runes := []rune(b.Lines[c.Line])
	col := c.Col
	if col > len(runes) {
		col = len(runes)
	}
	insert := []rune(c.Text)
	newRunes := append([]rune{}, runes[:col]...)
	newRunes = append(newRunes, insert...)
	newRunes = append(newRunes, runes[col:]...)
	b.Lines[c.Line] = string(newRunes)
	b.Dirty = true
}

func (c *InsertStringCommand) Undo(b *buffer.Buffer) {
	if c.Line < 0 || c.Line >= len(b.Lines) {
		return
	}
	runes := []rune(b.Lines[c.Line])
	tLen := len([]rune(c.Text))
	col := c.Col
	if col+tLen > len(runes) {
		return
	}
	newRunes := append(runes[:col], runes[col+tLen:]...)
	b.Lines[c.Line] = string(newRunes)
	b.Dirty = true
}

// DeleteSelectionCommand deletes a multi-line range and stores the deleted text for undo.
type DeleteSelectionCommand struct {
	StartLine, StartCol int
	EndLine, EndCol     int
	Deleted             string
}

func (c *DeleteSelectionCommand) Apply(b *buffer.Buffer) {
	if c.StartLine >= len(b.Lines) {
		return
	}
	if c.EndLine >= len(b.Lines) {
		c.EndLine = len(b.Lines) - 1
		c.EndCol = len([]rune(b.Lines[c.EndLine]))
	}

	startRunes := []rune(b.Lines[c.StartLine])
	sc := c.StartCol
	if sc > len(startRunes) {
		sc = len(startRunes)
	}

	if c.StartLine == c.EndLine {
		endRunes := []rune(b.Lines[c.StartLine])
		ec := c.EndCol
		if ec > len(endRunes) {
			ec = len(endRunes)
		}
		if sc > ec {
			sc = ec
		}
		c.Deleted = string(endRunes[sc:ec])
		b.Lines[c.StartLine] = string(startRunes[:sc]) + string(endRunes[ec:])
		b.Dirty = true
		return
	}

	endRunes := []rune(b.Lines[c.EndLine])
	ec := c.EndCol
	if ec > len(endRunes) {
		ec = len(endRunes)
	}

	// Build deleted text
	var del []rune
	del = append(del, startRunes[sc:]...)
	del = append(del, '\n')
	for l := c.StartLine + 1; l < c.EndLine; l++ {
		del = append(del, []rune(b.Lines[l])...)
		del = append(del, '\n')
	}
	del = append(del, endRunes[:ec]...)
	c.Deleted = string(del)

	// Merge start prefix with end suffix
	b.Lines[c.StartLine] = string(startRunes[:sc]) + string(endRunes[ec:])

	// Remove lines between
	if c.EndLine > c.StartLine {
		b.Lines = append(b.Lines[:c.StartLine+1], b.Lines[c.EndLine+1:]...)
	}
	b.Dirty = true
}

func (c *DeleteSelectionCommand) Undo(b *buffer.Buffer) {
	if c.StartLine >= len(b.Lines) {
		return
	}

	// Split current merged line at StartCol
	runes := []rune(b.Lines[c.StartLine])
	sc := c.StartCol
	if sc > len(runes) {
		sc = len(runes)
	}
	prefix := string(runes[:sc])
	suffix := string(runes[sc:])

	// Re-insert deleted text
	delLines := splitLines(c.Deleted)
	if len(delLines) == 1 {
		b.Lines[c.StartLine] = prefix + delLines[0] + suffix
	} else {
		newLines := make([]string, 0, len(b.Lines)+len(delLines)-1)
		newLines = append(newLines, b.Lines[:c.StartLine]...)
		newLines = append(newLines, prefix+delLines[0])
		for i := 1; i < len(delLines)-1; i++ {
			newLines = append(newLines, delLines[i])
		}
		newLines = append(newLines, delLines[len(delLines)-1]+suffix)
		newLines = append(newLines, b.Lines[c.StartLine+1:]...)
		b.Lines = newLines
	}
	b.Dirty = true
}

type PasteCommand struct {
	Line, Col int
	Text      string
	Suffix    string
}

func (c *PasteCommand) Apply(b *buffer.Buffer) {
	if c.Line < 0 || c.Line >= len(b.Lines) {
		return
	}
	lines := splitLines(c.Text)
	currentRunes := []rune(b.Lines[c.Line])
	col := c.Col
	if col > len(currentRunes) {
		col = len(currentRunes)
	}
	prefix := string(currentRunes[:col])

	if len(lines) == 1 {
		b.Lines[c.Line] = prefix + lines[0] + c.Suffix
	} else {
		newLines := make([]string, 0, len(b.Lines)+len(lines)-1)
		newLines = append(newLines, b.Lines[:c.Line]...)
		newLines = append(newLines, prefix+lines[0])
		for i := 1; i < len(lines)-1; i++ {
			newLines = append(newLines, lines[i])
		}
		newLines = append(newLines, lines[len(lines)-1]+c.Suffix)
		newLines = append(newLines, b.Lines[c.Line+1:]...)
		b.Lines = newLines
	}
	b.Dirty = true
}

func (c *PasteCommand) Undo(b *buffer.Buffer) {
	lines := splitLines(c.Text)
	if len(lines) == 1 {
		if c.Line < 0 || c.Line >= len(b.Lines) {
			return
		}
		runes := []rune(b.Lines[c.Line])
		tLen := len([]rune(lines[0]))
		col := c.Col
		if col+tLen > len(runes) {
			return
		}
		newRunes := append(runes[:col], runes[col+tLen:]...)
		b.Lines[c.Line] = string(newRunes)
	} else {
		if c.Line < 0 || c.Line >= len(b.Lines) {
			return
		}
		runes := []rune(b.Lines[c.Line])
		col := c.Col
		if col > len(runes) {
			col = len(runes)
		}
		restored := string(runes[:col]) + c.Suffix
		endLine := c.Line + len(lines) - 1
		if endLine >= len(b.Lines) {
			endLine = len(b.Lines) - 1
		}
		newLines := make([]string, 0, len(b.Lines)-(endLine-c.Line))
		newLines = append(newLines, b.Lines[:c.Line]...)
		newLines = append(newLines, restored)
		if endLine+1 < len(b.Lines) {
			newLines = append(newLines, b.Lines[endLine+1:]...)
		}
		b.Lines = newLines
	}
	b.Dirty = true
}

type BatchCommand struct {
	Commands []EditCommand
}

func (c *BatchCommand) Apply(b *buffer.Buffer) {
	for _, cmd := range c.Commands {
		cmd.Apply(b)
	}
}

func (c *BatchCommand) Undo(b *buffer.Buffer) {
	for i := len(c.Commands) - 1; i >= 0; i-- {
		c.Commands[i].Undo(b)
	}
}

// ReplaceLinesCommand replaces a contiguous range of buffer lines with new content.
// Used by sort, reverse, and unique line operations.
// The caller must set OldLines to the current buffer content being replaced
// and NewLines to the desired replacement.
type ReplaceLinesCommand struct {
	Start    int      // first line index (inclusive)
	OldLines []string // original lines (caller must populate before exec)
	NewLines []string // replacement lines
}

func (c *ReplaceLinesCommand) Apply(b *buffer.Buffer) {
	if c.Start < 0 || c.Start >= len(b.Lines) {
		return
	}
	end := c.Start + len(c.OldLines)
	if end > len(b.Lines) {
		end = len(b.Lines)
	}
	newBuf := make([]string, 0, len(b.Lines)-len(c.OldLines)+len(c.NewLines))
	newBuf = append(newBuf, b.Lines[:c.Start]...)
	newBuf = append(newBuf, c.NewLines...)
	newBuf = append(newBuf, b.Lines[end:]...)
	b.Lines = newBuf
	b.Dirty = true
}

func (c *ReplaceLinesCommand) Undo(b *buffer.Buffer) {
	if c.Start < 0 || c.Start >= len(b.Lines) {
		return
	}
	end := c.Start + len(c.NewLines)
	if end > len(b.Lines) {
		end = len(b.Lines)
	}
	newBuf := make([]string, 0, len(b.Lines)-len(c.NewLines)+len(c.OldLines))
	newBuf = append(newBuf, b.Lines[:c.Start]...)
	newBuf = append(newBuf, c.OldLines...)
	newBuf = append(newBuf, b.Lines[end:]...)
	b.Lines = newBuf
	b.Dirty = true
}

func splitLines(s string) []string {
	var lines []string
	start := 0
	for i, ch := range s {
		if ch == '\n' {
			lines = append(lines, s[start:i])
			start = i + 1
		}
	}
	lines = append(lines, s[start:])
	return lines
}

/**
 * Phase 8: Boolean History Tracking Tests
 *
 * Tests the tracking of faces through boolean operations using Modified() and IsDeleted() APIs.
 * This enables persistent references to survive boolean operations.
 *
 * @see docs/CAD-PIPELINE-REWORK.md Phase 8
 * @see docs/BOOLEAN-HISTORY-OPTIONS.md
 */

import { describe, it, expect, beforeAll } from "vitest";
import {
  initOCCT,
  setOC,
  booleanOpWithHistory,
  extrude,
  sketchProfileToFace,
  getPlaneNormal,
} from "../../src/kernel/index.js";
import { XY_PLANE } from "../../src/model/planes.js";
import { createRectangleProfile } from "../../src/model/sketchProfile.js";

describe("Boolean History Tracking (Phase 8)", () => {
  beforeAll(async () => {
    const oc = await initOCCT();
    setOC(oc);
  });

  describe("booleanOpWithHistory", () => {
    it("returns face mappings for union of overlapping boxes", () => {
      // Create two overlapping boxes
      const profile1 = createRectangleProfile(XY_PLANE, 20, 20, 0, 0);
      const face1 = sketchProfileToFace(profile1);
      const box1 = extrude(face1, getPlaneNormal(profile1.plane), 20);

      const profile2 = createRectangleProfile(XY_PLANE, 20, 20, 10, 0);
      const face2 = sketchProfileToFace(profile2);
      const box2 = extrude(face2, getPlaneNormal(profile2.plane), 20);

      // Perform union with history
      const result = booleanOpWithHistory(box1, box2, "union");

      expect(result.success).toBe(true);
      expect(result.shape).toBeDefined();
      expect(result.baseFaceMap).toBeDefined();
      expect(result.toolFaceMap).toBeDefined();

      // Both boxes have 6 faces
      expect(result.baseFaceMap!.length).toBe(6);
      expect(result.toolFaceMap!.length).toBe(6);

      // Count different fates
      const baseDeleted = result.baseFaceMap!.filter((m) => m.isDeleted).length;
      const baseModified = result.baseFaceMap!.filter(
        (m) => !m.isDeleted && m.outputHashes.length > 0
      ).length;
      const toolDeleted = result.toolFaceMap!.filter((m) => m.isDeleted).length;
      const toolModified = result.toolFaceMap!.filter(
        (m) => !m.isDeleted && m.outputHashes.length > 0
      ).length;

      console.log(`Base: ${baseDeleted} deleted, ${baseModified} modified/unchanged`);
      console.log(`Tool: ${toolDeleted} deleted, ${toolModified} modified/unchanged`);

      // Some faces should be deleted (internal faces where boxes overlap)
      expect(baseDeleted + toolDeleted).toBeGreaterThan(0);

      // Some faces should be modified or unchanged
      expect(baseModified + toolModified).toBeGreaterThan(0);

      // Cleanup
      result.shape!.dispose();
      box1.dispose();
      box2.dispose();
      face1.dispose();
      face2.dispose();
    });

    it("returns face mappings for subtraction (cut)", () => {
      // Create base box and cutting box
      const profile1 = createRectangleProfile(XY_PLANE, 30, 30, 0, 0);
      const face1 = sketchProfileToFace(profile1);
      const baseBox = extrude(face1, getPlaneNormal(profile1.plane), 20);

      const profile2 = createRectangleProfile(XY_PLANE, 10, 10, 0, 0);
      const face2 = sketchProfileToFace(profile2);
      const cutter = extrude(face2, getPlaneNormal(profile2.plane), 30);

      // Perform subtraction with history
      const result = booleanOpWithHistory(baseBox, cutter, "subtract");

      expect(result.success).toBe(true);
      expect(result.shape).toBeDefined();
      expect(result.baseFaceMap).toBeDefined();
      expect(result.toolFaceMap).toBeDefined();

      // Check that we get history for both shapes
      expect(result.baseFaceMap!.length).toBe(6);
      expect(result.toolFaceMap!.length).toBe(6);

      // In a cut, the tool faces that create the pocket should be tracked
      // Some base faces should be modified (the top face gets a hole)
      const baseModified = result.baseFaceMap!.filter(
        (m) => !m.isDeleted && m.outputHashes.length > 1
      );
      console.log(`Base faces split into multiple: ${baseModified.length}`);

      // Cleanup
      result.shape!.dispose();
      baseBox.dispose();
      cutter.dispose();
      face1.dispose();
      face2.dispose();
    });

    it("tracks unchanged faces correctly", () => {
      // Create two non-overlapping boxes that only touch at an edge
      const profile1 = createRectangleProfile(XY_PLANE, 10, 10, -10, 0);
      const face1 = sketchProfileToFace(profile1);
      const box1 = extrude(face1, getPlaneNormal(profile1.plane), 10);

      const profile2 = createRectangleProfile(XY_PLANE, 10, 10, 10, 0);
      const face2 = sketchProfileToFace(profile2);
      const box2 = extrude(face2, getPlaneNormal(profile2.plane), 10);

      // Perform union with history
      const result = booleanOpWithHistory(box1, box2, "union");

      expect(result.success).toBe(true);

      // Most faces should be unchanged (outputHash === inputHash)
      const baseUnchanged = result.baseFaceMap!.filter(
        (m) => !m.isDeleted && m.outputHashes.length === 1 && m.outputHashes[0] === m.inputHash
      );
      const toolUnchanged = result.toolFaceMap!.filter(
        (m) => !m.isDeleted && m.outputHashes.length === 1 && m.outputHashes[0] === m.inputHash
      );

      console.log(`Base unchanged: ${baseUnchanged.length}/6`);
      console.log(`Tool unchanged: ${toolUnchanged.length}/6`);

      // Most faces should survive unchanged for non-overlapping boxes
      expect(baseUnchanged.length + toolUnchanged.length).toBeGreaterThanOrEqual(8);

      // Cleanup
      result.shape!.dispose();
      box1.dispose();
      box2.dispose();
      face1.dispose();
      face2.dispose();
    });

    it("provides output hashes that can be used for tracking", () => {
      // Create overlapping boxes
      const profile1 = createRectangleProfile(XY_PLANE, 20, 20, 0, 0);
      const face1 = sketchProfileToFace(profile1);
      const box1 = extrude(face1, getPlaneNormal(profile1.plane), 20);

      const profile2 = createRectangleProfile(XY_PLANE, 20, 20, 5, 5);
      const face2 = sketchProfileToFace(profile2);
      const box2 = extrude(face2, getPlaneNormal(profile2.plane), 20);

      const result = booleanOpWithHistory(box1, box2, "union");

      expect(result.success).toBe(true);

      // Collect all output hashes from both face maps
      const allOutputHashes = new Set<number>();
      for (const mapping of result.baseFaceMap!) {
        for (const hash of mapping.outputHashes) {
          allOutputHashes.add(hash);
        }
      }
      for (const mapping of result.toolFaceMap!) {
        for (const hash of mapping.outputHashes) {
          allOutputHashes.add(hash);
        }
      }

      console.log(`Total unique output face hashes: ${allOutputHashes.size}`);

      // Should have some output faces
      expect(allOutputHashes.size).toBeGreaterThan(0);

      // Cleanup
      result.shape!.dispose();
      box1.dispose();
      box2.dispose();
      face1.dispose();
      face2.dispose();
    });
  });
});

/**
 * Fleet log history persistence + maintenance-flag derivation.
 *
 * Stores one compact FlightSummary per parsed log, grouped by vehicle, so the
 * Fleet Forensics view can show health trends and maintenance flags across many
 * aircraft over time without re-parsing every .bin. Capped per vehicle so the
 * store stays bounded.
 */
import Store from 'electron-store';
import type {
  FlightSummary,
  VehicleFlightHistory,
} from '../../shared/fleet-log-types.js';
export { deriveMaintenanceFlags } from '../../shared/fleet-log-maintenance.js';

const MAX_FLIGHTS_PER_VEHICLE = 200;

const historyStore = new Store<{ flights: FlightSummary[] }>({
  name: 'fleet-log-history',
  defaults: { flights: [] },
});

/** Append a flight summary, de-duplicating by file path (re-opening a log updates it). */
export function recordFlight(summary: FlightSummary): void {
  const all = historyStore.get('flights').filter((f) => f.path !== summary.path);
  all.push(summary);
  // Keep only the most recent N per vehicle to bound growth.
  const byVehicle = new Map<string, FlightSummary[]>();
  for (const f of all) {
    const list = byVehicle.get(f.vehicleKey) ?? [];
    list.push(f);
    byVehicle.set(f.vehicleKey, list);
  }
  const trimmed: FlightSummary[] = [];
  for (const list of byVehicle.values()) {
    list.sort((a, b) => b.startedAt - a.startedAt);
    trimmed.push(...list.slice(0, MAX_FLIGHTS_PER_VEHICLE));
  }
  historyStore.set('flights', trimmed);
}

/** All flights grouped by vehicle, newest first within each. */
export function getFleetHistory(): VehicleFlightHistory[] {
  const all = historyStore.get('flights');
  const byVehicle = new Map<string, FlightSummary[]>();
  for (const f of all) {
    const list = byVehicle.get(f.vehicleKey) ?? [];
    list.push(f);
    byVehicle.set(f.vehicleKey, list);
  }
  const out: VehicleFlightHistory[] = [];
  for (const [vehicleKey, flights] of byVehicle) {
    flights.sort((a, b) => b.startedAt - a.startedAt);
    out.push({ vehicleKey, vehicleLabel: flights[0]!.vehicleLabel, flights });
  }
  // Vehicles with the most recent activity first.
  out.sort((a, b) => (b.flights[0]?.startedAt ?? 0) - (a.flights[0]?.startedAt ?? 0));
  return out;
}

export function clearFleetHistory(): void {
  historyStore.set('flights', []);
}

/**
 * ParamHistoryModal
 *
 * Shows parameter checkpoint history for the connected board.
 * Allows restoring or deleting checkpoints.
 */

import React, { useState, useEffect, useCallback } from 'react';
import { History, ChevronDown, ChevronRight, RotateCcw, Trash2, X, Loader2 } from 'lucide-react';
import type { ParamCheckpoint, ParamChange } from '../../../shared/param-history-types';
import { useParameterStore } from '../../stores/parameter-store';

interface Props {
  boardUid: string;
  boardName: string;
  onClose: () => void;
  showToast: (message: string, type: 'success' | 'error' | 'info') => void;
}

function formatRelativeTime(timestamp: number): string {
  const now = Date.now();
  const diff = now - timestamp;
  const seconds = Math.floor(diff / 1000);
  const minutes = Math.floor(seconds / 60);
  const hours = Math.floor(minutes / 60);
  const days = Math.floor(hours / 24);

  if (seconds < 60) return 'Just now';
  if (minutes < 60) return `${minutes}m ago`;
  if (hours < 24) return `${hours}h ago`;
  if (days < 30) return `${days}d ago`;
  return new Date(timestamp).toLocaleDateString();
}

function formatTimestamp(timestamp: number): string {
  return new Date(timestamp).toLocaleString();
}

const ParamHistoryModal: React.FC<Props> = ({ boardUid, boardName, onClose, showToast }) => {
  const [checkpoints, setCheckpoints] = useState<ParamCheckpoint[]>([]);
  const [loading, setLoading] = useState(true);
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [restoring, setRestoring] = useState<string | null>(null);
  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);

  const setParameter = useParameterStore((s) => s.setParameterImmediate);

  const loadHistory = useCallback(async () => {
    setLoading(true);
    try {
      const result = await window.electronAPI?.getParamHistory(boardUid);
      setCheckpoints(result ?? []);
    } catch {
      setCheckpoints([]);
    } finally {
      setLoading(false);
    }
  }, [boardUid]);

  useEffect(() => {
    loadHistory();
  }, [loadHistory]);

  const handleRestore = useCallback(async (checkpointId: string) => {
    setRestoring(checkpointId);
    try {
      const result = await window.electronAPI?.restoreParamCheckpoint(boardUid, checkpointId);
      if (result?.success && result.changes) {
        let applied = 0;
        let failed = 0;
        for (const change of result.changes) {
          try {
            const success = await setParameter(change.paramId, change.oldValue);
            if (success) applied++;
            else failed++;
          } catch {
            failed++;
          }
        }
        if (applied > 0) {
          showToast(
            `Restored ${applied} parameter${applied !== 1 ? 's' : ''} to previous values${failed > 0 ? ` (${failed} failed)` : ''}. Write to Flash to persist.`,
            failed > 0 ? 'info' : 'success'
          );
        } else {
          showToast('Failed to restore parameters', 'error');
        }
      } else {
        showToast('Checkpoint not found', 'error');
      }
    } catch {
      showToast('Failed to restore checkpoint', 'error');
    } finally {
      setRestoring(null);
    }
  }, [boardUid, setParameter, showToast]);

  const handleDelete = useCallback(async (checkpointId: string) => {
    try {
      const result = await window.electronAPI?.deleteParamCheckpoint(boardUid, checkpointId);
      if (result?.success) {
        setCheckpoints(prev => prev.filter(c => c.id !== checkpointId));
        setConfirmDeleteId(null);
      }
    } catch {
      showToast('Failed to delete checkpoint', 'error');
    }
  }, [boardUid, showToast]);

  const toggleExpand = useCallback((id: string) => {
    setExpandedId(prev => prev === id ? null : id);
  }, []);

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
      <div className="bg-surface-solid border rounded-xl shadow-2xl max-w-2xl w-full mx-4 max-h-[80vh] flex flex-col">
        {/* Header */}
        <div className="px-6 py-4 border-b border-subtle flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 rounded-lg bg-blue-500/20 flex items-center justify-center">
              <History className="w-5 h-5 text-blue-400" />
            </div>
            <div>
              <h3 className="text-lg font-semibold text-content">Parameter History</h3>
              <p className="text-xs text-content-secondary">{boardName}</p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-2 text-content-secondary hover:text-content transition-colors rounded-lg hover:bg-surface-raised"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-auto px-6 py-4">
          {loading ? (
            <div className="flex items-center justify-center py-12 text-content-secondary">
              <Loader2 className="w-5 h-5 animate-spin mr-2" />
              Loading history...
            </div>
          ) : checkpoints.length === 0 ? (
            <div className="text-center py-12">
              <History className="w-10 h-10 text-content-tertiary mx-auto mb-3" />
              <p className="text-content-secondary text-sm">No history yet</p>
              <p className="text-content-tertiary text-xs mt-1">
                Changes are recorded each time you write to flash.
              </p>
            </div>
          ) : (
            <div className="space-y-2">
              {checkpoints.map((cp) => (
                <div
                  key={cp.id}
                  className="border-subtle rounded-lg overflow-hidden"
                >
                  {/* Checkpoint header */}
                  <button
                    onClick={() => toggleExpand(cp.id)}
                    className="w-full px-4 py-3 flex items-center gap-3 hover:bg-surface transition-colors text-left"
                  >
                    {expandedId === cp.id ? (
                      <ChevronDown className="w-4 h-4 text-content-secondary shrink-0" />
                    ) : (
                      <ChevronRight className="w-4 h-4 text-content-secondary shrink-0" />
                    )}
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2">
                        <span className="text-sm text-content truncate">
                          {cp.changes.length <= 3
                            ? <span className="font-mono">{cp.changes.map(c => c.paramId).join(', ')}</span>
                            : `${cp.changes.length} parameters changed`}
                        </span>
                        {cp.label && (
                          <span className="text-xs text-content-secondary truncate">{cp.label}</span>
                        )}
                      </div>
                      <div className="flex items-center gap-2 mt-0.5">
                        <span className="text-xs text-content-tertiary" title={formatTimestamp(cp.timestamp)}>
                          {formatRelativeTime(cp.timestamp)}
                        </span>
                      </div>
                    </div>

                    {/* Actions */}
                    <div className="flex items-center gap-1.5 shrink-0" onClick={e => e.stopPropagation()}>
                      <button
                        onClick={() => handleRestore(cp.id)}
                        disabled={restoring !== null}
                        className="px-2.5 py-1.5 text-xs font-medium rounded-md bg-blue-500/10 hover:bg-blue-500/20 text-blue-400 transition-colors flex items-center gap-1.5 disabled:opacity-50"
                        title="Restore these parameters (sets values in RAM, then Write to Flash to persist)"
                      >
                        {restoring === cp.id ? (
                          <Loader2 className="w-3.5 h-3.5 animate-spin" />
                        ) : (
                          <RotateCcw className="w-3.5 h-3.5" />
                        )}
                        Restore
                      </button>
                      {confirmDeleteId === cp.id ? (
                        <div className="flex items-center gap-1">
                          <button
                            onClick={() => handleDelete(cp.id)}
                            className="px-2 py-1.5 text-xs font-medium rounded-md bg-red-500/20 text-red-400 hover:bg-red-500/30 transition-colors"
                          >
                            Confirm
                          </button>
                          <button
                            onClick={() => setConfirmDeleteId(null)}
                            className="px-2 py-1.5 text-xs font-medium rounded-md text-content-secondary hover:text-content transition-colors"
                          >
                            Cancel
                          </button>
                        </div>
                      ) : (
                        <button
                          onClick={() => setConfirmDeleteId(cp.id)}
                          className="p-1.5 text-content-tertiary hover:text-red-400 transition-colors rounded-md hover:bg-surface-raised"
                          title="Delete checkpoint"
                        >
                          <Trash2 className="w-3.5 h-3.5" />
                        </button>
                      )}
                    </div>
                  </button>

                  {/* Expanded changes table */}
                  {expandedId === cp.id && (
                    <div className="px-4 pb-3 border-t border-subtle">
                      <table className="w-full text-xs mt-2">
                        <thead>
                          <tr className="text-content-tertiary uppercase">
                            <th className="pb-1.5 text-left font-medium">Parameter</th>
                            <th className="pb-1.5 text-right font-medium">Old Value</th>
                            <th className="pb-1.5 text-center font-medium px-2"></th>
                            <th className="pb-1.5 text-left font-medium">New Value</th>
                          </tr>
                        </thead>
                        <tbody className="divide-y divide-subtle/30">
                          {cp.changes.map((change, idx) => (
                            <tr key={idx}>
                              <td className="py-1.5 font-mono text-content-secondary">{change.paramId}</td>
                              <td className="py-1.5 text-right font-mono text-blue-400/70">{change.oldValue}</td>
                              <td className="py-1.5 text-center text-content-tertiary">→</td>
                              <td className="py-1.5 font-mono text-amber-400/70">{change.newValue}</td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  )}
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="px-6 py-3 border-t border-subtle flex justify-between items-center">
          <span className="text-xs text-content-tertiary">
            {checkpoints.length} checkpoint{checkpoints.length !== 1 ? 's' : ''}
          </span>
          <button
            onClick={onClose}
            className="px-4 py-2 text-sm text-content-secondary hover:text-content transition-colors"
          >
            Close
          </button>
        </div>
      </div>
    </div>
  );
};

export default ParamHistoryModal;
